CBU_st.name='CBU';
CBU_st.lat=35.62;
CBU_st.lon=140.06;
CBU_st.alt=0;
CBU_st.env='Coast';
CBU_st.footp='U';
%%
% CBU was received as monthly txt files and loaded via 
%adapt the parameter names 
TCBU_h = renamevars(TCBU_h, "Gsca", "");
TCBU_h = renamevars(TCBU_h, "Gsca", "BsG_S");
TCBU_h = renamevars(TCBU_h, "Rsca", "BsR_S");
TCBU_h = renamevars(TCBU_h, "Bbck", "BsB_S");
TCBU_h = renamevars(TCBU_h, "Gbck", "BbsG_S");
TCBU_h = renamevars(TCBU_h, "Rbck", "BbsR_S");
TCBU_h = renamevars(TCBU_h, "TI", "T");
TCBU_h = renamevars(TCBU_h, "x370nm", "Ba1_A");
TCBU_h = renamevars(TCBU_h, "x470nm", "Ba2_A");
TCBU_h = renamevars(TCBU_h, "x520nm", "Ba3_A");
TCBU_h = renamevars(TCBU_h, "x590nm", "Ba4_A");
TCBU_h = renamevars(TCBU_h, "x660nm", "Ba5_A");
TCBU_h = renamevars(TCBU_h, "x880nm", "Ba6_A");
TCBU_h = renamevars(TCBU_h, "x950nm", "Ba7_A");
% compute the daily median
CBU_d=retime(TCBU_h,'daily',@nanmedian);
%%
first_date=CBU_rd.Time(1) %[output:7da9f556]
last_date=CBU_rd.Time(end) %[output:774076b8]
names=fieldnames(CBU_rd);
c=startsWith(names,'Bs');
names_sc=names(c);
names_sc=names_sc(1:4,1); %remove names with g=STD and N=nb of data in hourly mean
c=startsWith(names,'Bbs');
names_bsc=names(c);
names_bsc=names_bsc(1:4,1);
c=endsWith(names,'A11');
names_clap=names(c);
names_clap=names_clap(1:3,1);
c=endsWith(names,'A81');
names_AE31=names(c);
names_AE31=names_AE31(1:7,1);
c=endsWith(names,'A82');
names_AE33=names(c);
names_AE33=names_AE33(22:28,1);
% prctile(CBU_rd.U_S,[5 50 95]) RH not included, always around 0% at CBU
%%
% plot in the live script
c=contains(names,{'g','N'}); 
names_delete=names(c);
CBU_rd_short=removevars(CBU_rd,names_delete);
plotFigControl(CBU_rd_short, CBU_st.name); %[output:47bbefa8] %[output:4f77c86b] %[output:757a2e7f]
% it is not possible to plot Bbs, 
% 1 size cut, ok
% sc: ok, max in CBUmer, with negatives
%%
% break point detection
break_CBU_scat=change_point_analysis_V3(CBU_rd_short,names_sc,0.05,'CBU','neph SC');
T_CBU_scat=make_table_breakpoints(break_CBU_scat,names_sc);

break_CBU_bscat=change_point_analysis_V3(CBU_rd_short,names_bsc(1:3,:),0.05,'CBU','neph BSC');
T_CBU_bscat=make_table_breakpoints(break_CBU_bscat,names_bsc(1:3,:));
%%

%construct abs from AE31 until 2014 and AE33 thereafter
P1=timerange('1979-01-01','2015-01-01');
P2=timerange('2015-01-01','2026-01-01');
for i=1:length(names_AE33)
    names_AE{i}=strcat('Ba',num2str(i));
CBU_rd_short.(names_AE33{i}(1:3))=[CBU_rd_short.(names_AE31{i})(P1); CBU_rd_short.(names_AE33{i})(P2)];
end
break_CBU_abs=change_point_analysis_V3(CBU_rd_short,names_AE,0.05,'CBU','AE31+AE33');
T_CBU_abs=make_table_breakpoints(break_CBU_abs,names_AE);
%%
%test the break point with the jonction at 1.1.2016
P1=timerange('1979-01-01','2016-01-01');
P2=timerange('2016-01-01','2026-01-01');
for i=1:length(names_AE33)
    names_AE{i}=strcat('Ba',num2str(i));
CBU_rd_short.(names_AE33{i}(1:3))=[CBU_rd_short.(names_AE31{i})(P1); CBU_rd_short.(names_AE33{i})(P2)];
end
%begin 20026-->bas3, begin in 1979 --> abs2
break_CBU_abs2=change_point_analysis_V3(CBU_rd_short,names_AE,0.05,'CBU','AE31+AE33');
T_CBU_abs2=make_table_breakpoints(break_CBU_abs,names_AE);

P_ana=timerange('2005-01-01','2026-01-01');
break_CBU_abs3=change_point_analysis_V3(CBU_rd_short(P_ana,:),names_AE,0.05,'CBU','AE31+AE33');
T_CBU_abs3=make_table_breakpoints(break_CBU_abs3,names_AE);
%%
%test a homogenisation via the median of the deseasonalised/detrended data:
%not necessary due to break point analysis
%%
lambdaSC=[450;550;700]*ones(1,4);
lambdaAE=[467;530;660]*ones(1,4);
lambdaAE7=[370 470 520 590 660 880 950];
%to be compaticle with compute_exp_SSA, wavelengths should be B, G, R
c=startsWith( CBU_rd_short.Properties.VariableNames,'Bs1');
CBU_rd_short.Properties.VariableNames(c)={'BsB_S11'};
c=startsWith( CBU_rd_short.Properties.VariableNames,'Bs2');
CBU_rd_short.Properties.VariableNames(c)={'BsG_S11'};
c=startsWith( CBU_rd_short.Properties.VariableNames,'Bs3');
CBU_rd_short.Properties.VariableNames(c)={'BsR_S11'};
c=startsWith( CBU_rd_short.Properties.VariableNames,'Bbs1');
CBU_rd_short.Properties.VariableNames(c)={'BbsB_S11'};
c=startsWith( CBU_rd_short.Properties.VariableNames,'Bbs2');
CBU_rd_short.Properties.VariableNames(c)={'BbsG_S11'};
c=startsWith( CBU_rd_short.Properties.VariableNames,'Bbs3');
CBU_rd_short.Properties.VariableNames(c)={'BbsR_S11'};

%to compute exp and SSA, only one time series from AE should be kept
CBU_rd_shortx=CBU_rd_short;
names_shortx=fieldnames(CBU_rd_shortx);
c=endsWith(names_shortx,{'_A81','A82'});
CBU_rd_shortx(:,c)=[];

CBU_cal=compute_exp_SSA(CBU_rd_shortx,lambdaSC, lambdaAE);
%%
plotFigControl_cal(CBU_cal, CBU_st.name); %[output:4d18f984] %[output:876bc8f2] %[output:12fe3fda]

%%
%Questions:
%problems:

%SC: why nothing in blue from December 2005 to February 2011 ?
% no data from mid-June to mid December 2017: real hole or databank problem ?
%sc: why are the minima much lower from 1993 to2004 ?
%there is a large difference in maxima between 1986 and 1987, Is there any reason?
% there is a strange behavior in winter 1991-1992. Is there any reason to exclude these data?
% there is a change mostly visible in the backscatter in 2011 with higher values. This is also visible in the backscatter fraction. Do you have an explanation?
%the data from October 2018 to December 2018 are much lower than before. What is the reason?
% the BbsG/BbsR also has a change in 2011 with lower variability thereafter. just the same with the exponent. Any reason ?
% should we invalidate the large backscatter fraction extrema in September-October 2003 ?

%in 2013 we took only 2003-2010! Do we also restrict ourselves to data after 2003 = 
%%
CBU_tr=CBU_rd;
CBU_tr.y=year(CBU_tr.Time);
% begin at the beginning of a year: scat: february 1979, hole then 1980
% untilfeb 1981.
%begin bacscat: 2003
%end 2018
P=timerange('1979-01-01','2019-01-01');
CBU_tr=CBU_tr(P,:);
%by now, only exp with gr available.

% U < 5%: no trend in U and in dry
%don't use abs: too short
names=fieldnames(CBU_tr);
c= startsWith(names,["T1";"T0";"T_";"P_";"P1_";"P0_";"N";"U";"Ba"]) | endsWith(names,'_dry') | contains(names,'Q');
N=names(c);
for i=1:length(N)
    CBU_tr.(N{i})=[];
end

%backscat since 2003
names=fieldnames(CBU_tr);
P1=timerange('1979-01-01','2003-01-01');
c= startsWith(names,'Bbs');
N=names(c);
for i=1:length(N)
    CBU_tr.(N{i})(P1)=NaN;
end

%strange in 1991-1992: removre scat 4 oct 1991-24 march 1992
P2=timerange('1991-10-04','1992-03-24');
c= startsWith(names,'Bs');
N=names(c);
for i=1:length(N)
    CBU_tr.(N{i})(P2)=NaN;
end

%strange BbsF : invalidate all neph 23 sept 2003 to 28 oct 2003
P3=timerange('1993-09-23','1993-10-28');
c= startsWith(names,'B');
N=names(c);
for i=1:length(N)
    CBU_tr.(N{i})(P3)=NaN;
end

CBU_cal2=compute_exp_SSA(CBU_tr,lambdaSC, lambdaAE);
CBU_tr=outerjoin(CBU_tr, CBU_cal2);

%compute trend on G and expS_gr
CBU_tr.BsB_S11=[]; %[output:0acdc8b3]
CBU_tr.BsR_S11=[];
CBU_tr.BbsB_S11=[];
CBU_tr.BbsR_S11=[];
CBU_tr.expS_bg3=[];
CBU_tr.expS_br3=[];
%%
CBU_result=all_trend_STN(CBU_tr,CBU_st);
plot_10y_in_two(CBU_result,CBU_st);
%%
CBU_result_D=CBU_result;

